import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;
import java.util.concurrent.CompletableFuture;

public class Main {
    public static void main(String[] args) {
        HttpClient client = HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(3)).build();
        HttpRequest first = HttpRequest.newBuilder(URI.create("https://example.com/")).timeout(Duration.ofSeconds(5)).GET().build();
        HttpRequest second = HttpRequest.newBuilder(URI.create("https://example.com/")).timeout(Duration.ofSeconds(5)).GET().build();
        CompletableFuture<HttpResponse<String>> a = client.sendAsync(first, HttpResponse.BodyHandlers.ofString());
        CompletableFuture<HttpResponse<String>> b = client.sendAsync(second, HttpResponse.BodyHandlers.ofString());
        a.thenCombine(b, (left, right) -> left.statusCode() + " / " + right.statusCode())
            .whenComplete((summary, failure) -> {
                if (failure != null) System.err.println("At least one request failed: " + failure.getMessage());
                else System.out.println("HTTP statuses: " + summary);
            }).join();
    }
}
